import { ArrowLeft, ArrowRight, Bell, BookOpenText, CalendarDays, CalendarRange, Check, ChevronLeft, ChevronRight, CircleAlert, Clock3, Copy, Download, FileClock, GraduationCap, LayoutGrid, Link2, LogOut, Moon, Pencil, Plus, Printer, RefreshCw, Save, Search, ShieldCheck, Sparkles, Sun, Trash2, UserRound, UsersRound, X } from 'lucide-react';
import { isConfigured, supabase } from './lib/supabase.ts';
