type Page = 'schedule'|'statistics'|'audit'|'notifications'|'groups'|'users'|'profile'|'assignments'|'attendance'|'requests';
type View = 'week'|'month';
const emptyStr = '';
function AvatarCircle({profile,size=''}:{profile:Profile|null;size?:string}){const url=safeLink(profile?.avatar_url);return <div className={`avatar ${size}`}>{url?<img src={url} alt="Аватар користувача" referrerPolicy="no-referrer"/>:(profile?.full_name?.[0]||'К')}</div>;}
const emptyLesson=(day:string, role:Role, userId:string, groupId:string):LessonPayload=>({title:'',lesson_date:day,day_of_week:dayOfWeek(day),starts_at:'09:00',ends_at:'10:00',duration_minutes:60,teacher_id:role==='teacher'?userId:null,group_id:groupId||null,room:'',note:'',link:'',materials_url:'',homework:'',status:'scheduled',student_id:null});
const time=(s:string)=>s.slice(0,5);
const localDateTime=(s:string)=>new Intl.DateTimeFormat('uk-UA',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Kyiv'}).format(new Date(s));
const roleCanEdit=(role:Role,l:Lesson,userId:string)=>role==='admin'||(role==='teacher'&&l.teacher_id===userId);
const messageOf=(e:unknown)=>e instanceof Error?e.message:String(e);

function AuthScreen({onEnter}:{onEnter:(s:Session)=>void}){
  const [mode,setMode]=useState<'login'|'signup'|'reset'>('login');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [name,setName]=useState('');const [busy,setBusy]=useState(false);const [msg,setMsg]=useState('');
  async function submit(event:FormEvent){event.preventDefault();if(!supabase)return;setBusy(true);setMsg('');try{
    if(mode==='reset'){const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});if(error)throw error;setMsg('Лист для відновлення пароля надіслано. Перевір пошту.');}
    else if(mode==='signup'){const {data,error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin+window.location.pathname+window.location.search,data:{full_name:name.trim()}}});if(error)throw error;if(data.session)onEnter(data.session);else setMsg('Перевір пошту та підтвердь реєстрацію, потім увійди.');}
    else{const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;if(data.session)onEnter(data.session);}
  }catch(e){setMsg(`Помилка: ${messageOf(e)}`);}finally{setBusy(false);}}
  return <div className="auth-page"><div className="auth-brand"><div className="brand-mark"><BookOpenText size={23}/></div><span>study<span className="blue">flow.</span></span></div><div className="auth-grid"><div className="auth-intro"><div className="eyebrow">НАВЧАННЯ БЕЗ ХАОСУ</div><h1>Твій час.<br/><em>Твій розклад.</em></h1><p>Єдиний простір для студентів, викладачів та адміністраторів. Заняття, групи, зміни й сповіщення — разом.</p><div className="auth-benefits"><span><CalendarDays size={19}/> Календар на всі дати</span><span><ShieldCheck size={19}/> Захищені ролі</span><span><Bell size={19}/> Сповіщення про зміни</span></div></div><div className="auth-card"><div className="auth-icon"><GraduationCap size={29}/></div><h2>{mode==='signup'?'Створити акаунт':mode==='reset'?'Відновлення пароля' :'З поверненням'}</h2><p>{mode==='login'?'Увійди, щоб побачити свій навчальний простір':mode==='signup'?'Створи обліковий запис для доступу до розкладу':'Ми надішлемо лист із подальшими інструкціями'}</p><form onSubmit={submit} className="stack-form">{mode==='signup'&&<label>Ім'я та прізвище<input required maxLength={100} value={name} onChange={e=>setName(e.target.value)} placeholder="Наприклад, Ілля Борщук"/></label>}<label>Електронна пошта<input type="email" autoComplete="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label>{mode!=='reset'&&<label>Пароль<input type="password" autoComplete={mode==='signup'?'new-password':'current-password'} required minLength={6} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Мінімум 6 символів"/></label>}{msg&&<div className="message">{msg}</div>}<button className="btn primary wide" disabled={busy} type="submit">{busy?'Зачекай…':mode==='signup'?'Зареєструватися':mode==='reset'?'Надіслати лист':'Увійти'} <ArrowRight size={17}/></button></form><div className="auth-switch">{mode==='login'?<><button onClick={()=>{setMode('signup');setMsg('');}}>Створити акаунт</button><button onClick={()=>{setMode('reset');setMsg('');}}>Забув пароль?</button></>:<button onClick={()=>{setMode('login');setMsg('');}}><ArrowLeft size={14}/> Повернутися до входу</button>}</div><small>Роль адміністратора призначається тільки власником проєкту.</small></div></div></div>;
}

function ResetPassword({onDone}:{onDone:()=>void}){const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');async function submit(e:FormEvent){e.preventDefault();if(!supabase)return;setBusy(true);const {error}=await supabase.auth.updateUser({password});setBusy(false);if(error)setMessage(error.message);else{setMessage('Пароль успішно змінено');onDone();}}return <div className="center-card"><h2>Новий пароль</h2><p>Встанови новий пароль для свого акаунта</p><form className="stack-form" onSubmit={submit}><label>Новий пароль<input type="password" minLength={6} required autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="btn primary" disabled={busy} type="submit">Зберегти новий пароль</button>{message&&<div className="message">{message}</div>}</form></div>;}

function LessonEditor({lesson,initialDay,role,viewer,groups,teachers,students,assignments,selectedGroup,onSave,onRepeat,onSeriesEdit,onRemove,onClose,busy}:{lesson:Lesson|null;initialDay:string;role:Role;viewer:string;groups:Group[];teachers:Profile[];students:Profile[];assignments:Assignment[];selectedGroup:string;onSave:(p:LessonPayload)=>Promise<void>;onRepeat:(p:LessonPayload,mode:'daily'|'weekly'|'custom',until:string,weekdays:number[])=>Promise<void>;onSeriesEdit:(p:LessonPayload,scope:'future'|'all')=>Promise<void>;onRemove:()=>Promise<void>;onClose:()=>void;busy:boolean}){
  const [form,setForm]=useState<LessonPayload>(lesson?{...lesson,lesson_date:lesson.lesson_date,starts_at:time(lesson.starts_at),ends_at:time(lesson.ends_at)}:emptyLesson(initialDay,role,viewer,selectedGroup));
  const [repeatMode,setRepeatMode]=useState<'once'|'daily'|'weekly'|'custom'>('once');const [repeatUntil,setRepeatUntil]=useState(addDays(initialDay,28));const [weekdays,setWeekdays]=useState<number[]>([dayOfWeek(initialDay)]);const [editScope,setEditScope]=useState<'this'|'future'|'all'>('this');const [err,setErr]=useState('');const update=<K extends keyof LessonPayload>(k:K,v:LessonPayload[K])=>setForm(f=>{const next:LessonPayload={...f,[k]:v};if(lesson&&(k==='lesson_date'||k==='starts_at'||k==='ends_at')&&(next.lesson_date!==lesson.lesson_date||next.starts_at!==time(lesson.starts_at)||next.ends_at!==time(lesson.ends_at))&&next.status!=='cancelled'&&next.status!=='completed')next.status='rescheduled';return next;});
  function submit(e:FormEvent){e.preventDefault();const mins=calcDuration(form.starts_at,form.ends_at);if(mins<=0||mins>480){setErr('Час завершення має бути пізніше початку (до 8 годин).');return;}if(form.link&&!safeLink(form.link)||form.materials_url&&!safeLink(form.materials_url)){setErr('Посилання повинно починатися з https:// або http://');return;}if(form.status==='rescheduled'&&!lesson){setErr('Створи урок, а потім перенеси його на нову дату.');return;}if(form.status==='rescheduled'&&lesson&&lesson.status!=='rescheduled'&&form.lesson_date===lesson.lesson_date&&form.starts_at===time(lesson.starts_at)&&form.ends_at===time(lesson.ends_at)){setErr('Для перенесення зміни дату або час.');return;}const p={...form,day_of_week:dayOfWeek(form.lesson_date),duration_minutes:mins,title:form.title.trim(),link:safeLink(form.link),materials_url:safeLink(form.materials_url)};if(!lesson&&repeatMode!=='once'){if(repeatUntil<form.lesson_date){setErr('Кінцева дата не може бути раніше початкової.');return;}setErr('');void onRepeat(p,repeatMode,repeatUntil,weekdays);return;}if(lesson?.series_id&&editScope!=='this'){setErr('');void onSeriesEdit(p,editScope);return;}setErr('');void onSave(p);}
  return <div className="overlay" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose();}}><div className="dialog" role="dialog" aria-modal="true" aria-labelledby="edit-title"><div className="dialog-head"><div><div className="eyebrow">НАВЧАЛЬНИЙ КАЛЕНДАР</div><h2 id="edit-title">{lesson?'Редагувати заняття':'Нове заняття'}</h2><p>Зміни автоматично відобразяться у всіх пов’язаних розкладах.</p></div><button className="icon-btn" disabled={busy} onClick={onClose} aria-label="Закрити"><X size={20}/></button></div><form onSubmit={submit} className="edit-form"><label className="full">Назва заняття *<input autoFocus value={form.title} onChange={e=>update('title',e.target.value)} required maxLength={120} placeholder="Англійська мова"/></label><label>Дата *<input type="date" required value={form.lesson_date} onChange={e=>update('lesson_date',e.target.value)}/></label><label>Статус<select value={form.status} onChange={e=>update('status',e.target.value as LessonPayload['status'])}><option value="scheduled">Заплановане</option><option value="completed">Проведене</option><option value="rescheduled">Перенесене</option><option value="cancelled">Скасоване</option></select></label>{lesson&&form.status==='rescheduled'&&<div className="reschedule-explainer full"><strong>Перенесення заняття</strong><span>Було: {lesson.lesson_date} · {time(lesson.starts_at)}–{time(lesson.ends_at)}. Вкажи нові дату й час; попередні залишаться в історії.</span></div>}<label>Початок *<input type="time" required value={time(form.starts_at)} onChange={e=>update('starts_at',e.target.value)}/></label><label>Завершення *<input type="time" required value={time(form.ends_at)} onChange={e=>update('ends_at',e.target.value)}/></label><div className="form-inline-note full"><Clock3 size={15}/> Тривалість: {calcDuration(form.starts_at,form.ends_at)>0?durationText(calcDuration(form.starts_at,form.ends_at)):'некоректний час'}</div>{!lesson&&<div className="repeat-editor full"><label>Повторення<select value={repeatMode} onChange={e=>setRepeatMode(e.target.value as typeof repeatMode)}><option value="once">Без повторення</option><option value="daily">Щодня</option><option value="weekly">Щотижня</option><option value="custom">Вибрані дні тижня</option></select></label>{repeatMode!=='once'&&<><label>Повторювати до<input type="date" value={repeatUntil} min={form.lesson_date} onChange={e=>setRepeatUntil(e.target.value)}/></label>{repeatMode==='custom'&&<div className="repeat-days">{SHORT_DAYS.map((label,i)=><label key={i}><input type="checkbox" checked={weekdays.includes(i+1)} onChange={e=>setWeekdays(x=>e.target.checked?[...x,i+1]:x.filter(v=>v!==i+1))}/>{label}</label>)}</div>}<p>Перед створенням усі уроки перевіряються на конфлікти. Якщо один конфліктує, серія не збережеться.</p></>}</div>}{lesson?.series_id&&<div className="repeat-editor full"><label>Змінити<select value={editScope} onChange={e=>setEditScope(e.target.value as typeof editScope)}><option value="this">Лише це заняття</option><option value="future">Це та наступні в серії</option><option value="all">Усю серію</option></select></label>{editScope!=='this'&&<p>Окремо скасовані й раніше перенесені уроки не будуть перезаписані. Масові зміни стосуються назви, дати, часу, примітки та статусу.</p>}</div>}<label>Навчальна група<select value={form.group_id||''} onChange={e=>setForm(f=>({...f,group_id:e.target.value||null,student_id:e.target.value?null:f.student_id}))}><option value="">Спільне заняття</option>{groups.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></label><label>Студент (індивідуальне заняття)<select value={form.student_id||''} onChange={e=>setForm(f=>({...f,student_id:e.target.value||null,group_id:e.target.value?null:f.group_id}))}><option value="">Без студента</option>{students.filter(p=>!form.teacher_id||assignments.some(a=>a.teacher_id===form.teacher_id&&a.student_id===p.id)).map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>Викладач<select value={form.teacher_id||''} disabled={role==='teacher'} onChange={e=>update('teacher_id',e.target.value||null)}><option value="">Не призначено</option>{teachers.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label>{role==='admin'&&lesson&&<label className="full">Причина заміни викладача<input maxLength={500} value={form.substitution_reason||''} onChange={e=>update('substitution_reason',e.target.value)} placeholder="Наприклад, хвороба викладача"/></label>}<label>Аудиторія<input maxLength={120} value={form.room} onChange={e=>update('room',e.target.value)} placeholder="Ауд. 105 / Онлайн"/></label><label>Посилання на заняття<input type="url" maxLength={500} value={form.link} onChange={e=>update('link',e.target.value)} placeholder="https://meet.google.com/..."/></label><label className="full">Примітка<textarea maxLength={500} rows={2} value={form.note} onChange={e=>update('note',e.target.value)}/></label><label className="full">Домашнє завдання<textarea maxLength={3000} rows={2} value={form.homework} onChange={e=>update('homework',e.target.value)}/></label><label className="full">Посилання на матеріали<input type="url" maxLength={500} value={form.materials_url} onChange={e=>update('materials_url',e.target.value)} placeholder="https://drive.google.com/..."/></label>{err&&<div role="alert" className="message error full">{err}</div>}<div className="dialog-actions full">{lesson&&<button className="btn danger" type="button" onClick={()=>void onRemove()} disabled={busy}><Trash2 size={16}/> Видалити</button>}<button className="btn light" type="button" onClick={onClose}>Скасувати</button><button className="btn primary" type="submit" disabled={busy}><Save size={16}/>{busy?'Збереження…':'Зберегти'}</button></div></form></div></div>;
}

function ScheduleCard({lesson,onClick,onDetails,teacher,student,group,canEdit}:{lesson:Lesson;onClick:()=>void;onDetails:()=>void;teacher:string;student:string;group:string;canEdit:boolean}){
  return <article draggable={canEdit} onDragStart={e=>{if(canEdit)e.dataTransfer.setData('text/studyflow-lesson',lesson.id);}} className={`lesson ${lesson.status==='cancelled'?'cancelled':''}`}><div className="lesson-top"><span><Clock3 size={13}/>{time(lesson.starts_at)}–{time(lesson.ends_at)}</span>{canEdit&&<button className="mini-edit" title="Редагувати" aria-label="Редагувати заняття" onClick={onClick}><Pencil size={14}/></button>}</div><strong>{lesson.title}</strong><div className="lesson-meta">{lesson.student_id&&<span>Студент: {student||'Індивідуально'}</span>}{group&&<span>{group}</span>}{teacher&&<span>{teacher}</span>}{lesson.room&&<span>{lesson.room}</span>}</div><div className={`status status-${lesson.status}`}>{STATUS_LABEL[lesson.status]}</div>{lesson.homework&&<p className="lesson-description">Д/з: {lesson.homework}</p>}{lesson.note&&<p className="lesson-description">{lesson.note}</p>}<div className="lesson-links">{safeLink(lesson.link)&&<a target="_blank" rel="noreferrer" href={safeLink(lesson.link)}><Link2 size={13}/> Заняття</a>}{safeLink(lesson.materials_url)&&<a target="_blank" rel="noreferrer" href={safeLink(lesson.materials_url)}><BookOpenText size={13}/> Матеріали</a>}</div><small>{durationText(lesson.duration_minutes)}</small><button className="lesson-details-btn" type="button" onClick={onDetails}>Деталі заняття <ArrowRight size={14}/></button></article>;
}

export default function App(){
  const [session,setSession]=useState<Session|null>(null);const [recovering,setRecovering]=useState(false);const [authReady,setAuthReady]=useState(false);const [profile,setProfile]=useState<Profile|null>(null);const [profiles,setProfiles]=useState<Profile[]>([]);const [groups,setGroups]=useState<Group[]>([]);const [members,setMembers]=useState<Membership[]>([]);
  const [assignments,setAssignments]=useState<Assignment[]>([]);const [assignmentTeacher,setAssignmentTeacher]=useState('');const [assignmentStudent,setAssignmentStudent]=useState('');const [assignmentSubject,setAssignmentSubject]=useState('');const [pickedTeacher,setPickedTeacher]=useState('');const [lessons,setLessons]=useState<Lesson[]>([]);const [page,setPage]=useState<Page>('schedule');const [view,setView]=useState<View>('week');const [selectedDate,setSelectedDate]=useState(kyivToday);const [pickedGroup,setPickedGroup]=useState('');const [search,setSearch]=useState('');const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [toast,setToast]=useState('');const [edit,setEdit]=useState<{lesson:Lesson|null;date:string}|null>(null);const [lessonDetails,setLessonDetails]=useState<Lesson|null>(null);const [detailMoves,setDetailMoves]=useState<RescheduleEvent[]>([]);const [reschedules,setReschedules]=useState<RescheduleEvent[]>([]);const [notificationsFrom,setNotificationsFrom]=useState<Page>('schedule');const [attendanceLesson,setAttendanceLesson]=useState<Lesson|null>(null);const [requestLesson,setRequestLesson]=useState<Lesson|null>(null);const [inviteToken,setInviteToken]=useState(()=>new URLSearchParams(location.search).get('invite')||'');const [inviteBusy,setInviteBusy]=useState(false);const [dragProposal,setDragProposal]=useState<{lesson:Lesson;date:string;starts:string;ends:string}|null>(null);
  const [history,setHistory]=useState<AuditEntry[]>([]);const [notices,setNotices]=useState<Notice[]>([]);const [users,setUsers]=useState<UserRow[]>([]);const [profileName,setProfileName]=useState('');const [profileAvatar,setProfileAvatar]=useState('');const [profileCourse,setProfileCourse]=useState('');const [profileSpecialty,setProfileSpecialty]=useState('');const [profileFaculty,setProfileFaculty]=useState('');const [profileSpecialization,setProfileSpecialization]=useState('');const [profileBio,setProfileBio]=useState('');const [pickedStatus,setPickedStatus]=useState('');const [dark,setDark]=useState(()=>localStorage.getItem('studyflow-dark')==='yes');
  const role:Role=profile?.role||'student';const viewer=session?.user.id||emptyStr;const canCreate=role!=='student';const today=kyivToday();
  const days=view==='week'?weekDays(selectedDate):monthCells(selectedDate);
  const rangeStart=days[0];const rangeEnd=days[days.length-1];
  const teacherMap=useMemo(()=>Object.fromEntries(profiles.map(p=>[p.id,p.full_name])),[profiles]);
  const groupMap=useMemo(()=>Object.fromEntries(groups.map(g=>[g.id,g.name])),[groups]);
  const teachers=profiles.filter(p=>p.role==='teacher');const students=profiles.filter(p=>p.role==='student');
  const visibleLessons=useMemo(()=>lessons.filter(l=>(!pickedGroup||l.group_id===pickedGroup)&&(!pickedTeacher||l.teacher_id===pickedTeacher)&&(!pickedStatus||l.status===pickedStatus)&&(!search||[l.title,l.room,l.homework,teacherMap[l.teacher_id||'']||''].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>a.lesson_date.localeCompare(b.lesson_date)||a.starts_at.localeCompare(b.starts_at)),[lessons,pickedGroup,pickedTeacher,pickedStatus,search,teacherMap]);
  const stats=useMemo(()=>{const minutes=visibleLessons.filter(l=>l.status!=='cancelled').reduce((s,l)=>s+l.duration_minutes,0);return{total:visibleLessons.length,minutes,cancelled:visibleLessons.filter(l=>l.status==='cancelled').length,rescheduled:visibleLessons.filter(l=>l.status==='rescheduled').length,completed:visibleLessons.filter(l=>l.status==='completed').length};},[visibleLessons]);
  const onError=(e:unknown)=>{setError(messageOf(e));};
  const notify=(s:string)=>setToast(s);

  useEffect(()=>{if(!supabase){setAuthReady(true);return;}const db=supabase;void db.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true);});const {data:{subscription}}=db.auth.onAuthStateChange((event,s)=>{if(event==='PASSWORD_RECOVERY')setRecovering(true);setSession(s);setAuthReady(true);});return()=>subscription.unsubscribe();},[]);
  const reloadDirectory=useCallback(async()=>{const db=supabase;if(!db||!session)return;const [{data:p,error:pe},{data:g,error:ge},{data:m,error:me}]=await Promise.all([db.from('profiles').select('*'),db.from('study_groups').select('*').order('name'),db.from('group_members').select('*')]);if(pe||ge||me){onError(pe||ge||me);return;}setProfiles((p||[]) as Profile[]);setGroups((g||[]) as Group[]);setMembers((m||[]) as Membership[]);setProfile((p||[]).find(x=>x.id===session.user.id) as Profile||null);},[session]);
  useEffect(()=>{if(!session){setProfile(null);setLessons([]);return;}void reloadDirectory();},[session,reloadDirectory]);
  const reloadLessons=useCallback(async(silent=false)=>{const db=supabase;if(!db||!session)return;if(!silent)setLoading(true);const {data,error:e}=await db.from('lessons').select('*').gte('lesson_date',rangeStart).lte('lesson_date',rangeEnd).order('lesson_date').order('starts_at');if(e)onError(e);else{setLessons((data||[]) as Lesson[]);setError('');}setLoading(false);},[session,rangeStart,rangeEnd]);
  const reloadAssignments=useCallback(async()=>{const db=supabase;if(!db||!session)return;const {data,error:e}=await db.from('teacher_student_assignments').select('*').order('created_at',{ascending:false});if(e)onError(e);else setAssignments((data||[]) as Assignment[]);},[session]);
  const reloadReschedules=useCallback(async()=>{const db=supabase;if(!db||!session)return;const {data,error:e}=await db.from('lesson_reschedule_history').select('*').gte('old_date',rangeStart).lte('old_date',rangeEnd).order('changed_at',{ascending:false});if(e)onError(e);else setReschedules((data||[]) as RescheduleEvent[]);},[session,rangeStart,rangeEnd]);
  const reloadNotices=useCallback(async()=>{const db=supabase;if(!db||!session)return;const {data}=await db.from('notifications').select('*').order('created_at',{ascending:false}).limit(60);if(data)setNotices(data as Notice[]);},[session]);
  const reloadAudit=useCallback(async()=>{const db=supabase;if(!db||!session||role==='student')return;const {data,error:e}=await db.from('lesson_audit').select('*').order('occurred_at',{ascending:false}).limit(200);if(e)onError(e);else setHistory((data||[]) as AuditEntry[]);},[session,role]);
  const reloadUsers=useCallback(async()=>{const db=supabase;if(!db||!session||role!=='admin')return;const {data,error:e}=await db.rpc('admin_list_users');if(e)onError(e);else setUsers((data||[]) as UserRow[]);},[session,role]);
  useEffect(()=>{void reloadLessons();},[reloadLessons]);
  useEffect(()=>{void reloadAssignments();},[reloadAssignments]);
  useEffect(()=>{void reloadReschedules();},[reloadReschedules]);
  useEffect(()=>{const db=supabase;if(!db||!lessonDetails)return;let active=true;void db.from('lesson_reschedule_history').select('*').eq('lesson_id',lessonDetails.id).order('changed_at',{ascending:false}).then(({data,error:e})=>{if(!active)return;if(e)onError(e);else setDetailMoves((data||[]) as RescheduleEvent[]);});return()=>{active=false;};},[lessonDetails]);
  useEffect(()=>{void reloadNotices();const id=window.setInterval(()=>void reloadNotices(),45000);return()=>window.clearInterval(id);},[reloadNotices]);
  useEffect(()=>{if(page==='audit')void reloadAudit();if((page==='users'||page==='groups')&&role==='admin')void reloadUsers();},[page,reloadAudit,reloadUsers]);
  useEffect(()=>{const db=supabase;if(!db||!session)return;const ch=db.channel('studyflow-v2').on('postgres_changes',{event:'*',schema:'public',table:'lessons'},()=>void reloadLessons(true)).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications'},()=>void reloadNotices()).on('postgres_changes',{event:'INSERT',schema:'public',table:'lesson_reschedule_history'},()=>void reloadReschedules()).subscribe();const timer=window.setInterval(()=>{void reloadLessons(true);void reloadAssignments();void reloadReschedules();},45000);return()=>{window.clearInterval(timer);void db.removeChannel(ch);};},[session,reloadLessons,reloadNotices,reloadAssignments,reloadReschedules]);
  useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('studyflow-dark',dark?'yes':'no');},[dark]);
  useEffect(()=>{if(toast){const id=window.setTimeout(()=>setToast(''),4000);return()=>window.clearTimeout(id);}},[toast]);
  useEffect(()=>{setProfileName(profile?.full_name||'');setProfileAvatar(profile?.avatar_url||'');setProfileCourse(profile?.course?.toString()||'');setProfileSpecialty(profile?.specialty||'');setProfileFaculty(profile?.faculty||'');setProfileSpecialization(profile?.specialization||'');setProfileBio(profile?.bio||'');},[profile]);

  async function createSeries(payload:LessonPayload,mode:'daily'|'weekly'|'custom',until:string,weekdays:number[]){const db=supabase;if(!db)return;setBusy(true);try{const {error:e}=await db.rpc('create_recurring_lessons',{p_title:payload.title,p_start:payload.lesson_date,p_until:until,p_frequency:mode,p_weekdays:weekdays,p_start_time:payload.starts_at,p_end_time:payload.ends_at,p_teacher:payload.teacher_id,p_student:payload.student_id,p_group:payload.group_id,p_room:payload.room,p_note:payload.note,p_link:payload.link,p_homework:payload.homework,p_materials:payload.materials_url});if(e)throw e;setEdit(null);await reloadLessons(true);notify('Серію занять створено');}catch(e){onError(e);}finally{setBusy(false);}}
  async function editSeries(payload:LessonPayload,scope:'future'|'all'){const db=supabase;if(!db||!edit?.lesson)return;setBusy(true);try{const {error:e}=await db.rpc('edit_recurring_lessons',{p_lesson:edit.lesson.id,p_scope:scope,p_patch:{title:payload.title,lesson_date:payload.lesson_date,starts_at:payload.starts_at,ends_at:payload.ends_at,note:payload.note,room:payload.room,status:payload.status}});if(e)throw e;setEdit(null);await reloadLessons(true);await reloadReschedules();notify('Серію оновлено без дублювання занять');}catch(e){onError(e);}finally{setBusy(false);}}
  async function acceptInvite(){if(!supabase||!inviteToken)return;setInviteBusy(true);try{const {error:e}=await supabase.rpc('accept_group_invitation',{p_token:inviteToken});if(e)throw e;setInviteToken('');window.history.replaceState(null,'',location.pathname);await reloadDirectory();notify('Тебе додано до навчальної групи');}catch(e){onError(e);}finally{setInviteBusy(false);}}
  async function confirmDrag(){const db=supabase;if(!db||!dragProposal)return;setBusy(true);try{const {lesson,date,starts,ends}=dragProposal;const {error:e}=await db.from('lessons').update({lesson_date:date,starts_at:starts,ends_at:ends,status:'rescheduled'}).eq('id',lesson.id);if(e)throw e;setDragProposal(null);await reloadLessons(true);await reloadReschedules();notify('Урок перенесено, учасників повідомлено');}catch(e){onError(e);}finally{setBusy(false);}}
  async function saveLesson(payload:LessonPayload){const db=supabase;if(!db||!edit||!session)return;setBusy(true);try{const original=edit.lesson;const result=original?await db.from('lessons').update(payload).eq('id',original.id):await db.from('lessons').insert({...payload,created_by:viewer,created_by_name:profile?.full_name||'Користувач'});if(result.error)throw result.error;setEdit(null);await reloadLessons(true);await reloadReschedules();notify(original?'Зміни збережено та записано в історію':'Нове заняття створено');}catch(e){onError(e);}finally{setBusy(false);}}
  async function deleteLesson(){const db=supabase;if(!db||!edit?.lesson||!window.confirm(`Видалити «${edit.lesson.title}»? Зміна залишиться в історії.`))return;setBusy(true);try{const {error:e}=await db.from('lessons').delete().eq('id',edit.lesson.id);if(e)throw e;setEdit(null);await reloadLessons(true);notify('Заняття видалено, історію збережено');}catch(e){onError(e);}finally{setBusy(false);}}
  async function updateProfile(event:FormEvent){event.preventDefault();const db=supabase;if(!db||!profile)return;const name=profileName.trim();if(!name)return;setBusy(true);const {error:e}=await db.from('profiles').update({full_name:name,avatar_url:safeLink(profileAvatar)||null,course:profileCourse?Number(profileCourse):null,specialty:profileSpecialty.trim()||null,faculty:profileFaculty.trim()||null,specialization:profileSpecialization.trim()||null,bio:profileBio.trim()||null}).eq('id',profile.id);if(e)onError(e);else{await reloadDirectory();notify('Профіль збережено');}setBusy(false);}
  async function addAssignment(e:FormEvent){e.preventDefault();const db=supabase;if(!db||!assignmentTeacher||!assignmentStudent||!assignmentSubject.trim())return;const {error:e1}=await db.from('teacher_student_assignments').insert({teacher_id:assignmentTeacher,student_id:assignmentStudent,subject:assignmentSubject.trim()});if(e1)onError(e1);else{setAssignmentSubject('');notify('Призначення додано');await reloadAssignments();}}
  async function deleteAssignment(id:string){const db=supabase;if(!db||!window.confirm('Прибрати закріплення студента за викладачем?'))return;const {error:e}=await db.from('teacher_student_assignments').delete().eq('id',id);if(e)onError(e);else{notify('Призначення вилучено');await reloadAssignments();await reloadLessons(true);}}
  async function changeRole(id:string,otherRole:Role){const db=supabase;if(!db||!window.confirm(`Змінити роль користувача на «${ROLE_LABEL[otherRole]}»?`))return;const {error:e}=await db.from('profiles').update({role:otherRole}).eq('id',id);if(e)onError(e);else{await reloadDirectory();await reloadUsers();notify('Роль оновлено');}}
  function openNotifications(){if(page!=='notifications')setNotificationsFrom(page);setPage('notifications');}
  async function openNoticeLesson(n:Notice){const db=supabase;if(!db||!n.lesson_id)return;const {data,error:e}=await db.from('lessons').select('*').eq('id',n.lesson_id).maybeSingle();if(e){onError(e);return;}if(data){const lesson=data as Lesson;setSelectedDate(lesson.lesson_date);setView('week');setPage('schedule');setLessonDetails(lesson);setDetailMoves([]);}else notify('Заняття видалено або немає доступу.');}
  async function markNotice(id:string){const db=supabase;if(!db)return;const {error:e}=await db.rpc('mark_notification_read',{p_id:id});if(e)onError(e);else await reloadNotices();}
  function movePeriod(dir:number){setSelectedDate(view==='week'?addDays(selectedDate,dir*7):addMonths(selectedDate,dir));}
  function exportCsv(){const rows=[['Дата','Початок','Завершення','Назва','Статус','Викладач','Група','Аудиторія','Домашнє завдання'],...visibleLessons.map(l=>[l.lesson_date,time(l.starts_at),time(l.ends_at),l.title,STATUS_LABEL[l.status],teacherMap[l.teacher_id||'']||'',groupMap[l.group_id||'']||'',l.room,l.homework])];const csv='\ufeff'+rows.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`studyflow-${rangeStart}-${rangeEnd}.csv`;a.click();URL.revokeObjectURL(url);}
  if(!isConfigured)return <div className="center-card"><CircleAlert size={28}/><h2>Потрібне підключення Supabase</h2><p>Задай VITE_SUPABASE_URL та VITE_SUPABASE_PUBLISHABLE_KEY у налаштуваннях Vercel.</p></div>;
  if(!authReady||session&&!profile)return <div className="center-card"><div className="spinner"/><h2>Завантажуємо StudyFlow…</h2><p>Якщо завантаження триває довго, перевір міграцію бази даних v2.</p><button className="btn light" onClick={()=>void reloadDirectory()}>Повторити</button>{error&&<div className="message error">{error}</div>}</div>;
  if(!session)return <AuthScreen onEnter={setSession}/>;
  if(recovering)return <ResetPassword onDone={()=>setRecovering(false)}/>;
  const unread=notices.filter(n=>!n.read_at).length;
  const menu:{id:Page;icon:typeof CalendarDays;label:string;allow:boolean}[]=[{id:'schedule',icon:CalendarDays,label:'Календар',allow:true},{id:'statistics',icon:LayoutGrid,label:'Статистика',allow:true},{id:'attendance',icon:Check,label:'Відвідуваність',allow:true},{id:'requests',icon:CalendarRange,label:'Заявки на перенесення',allow:true},{id:'notifications',icon:Bell,label:'Сповіщення',allow:true},{id:'audit',icon:FileClock,label:'Історія змін',allow:role!=='student'},{id:'groups',icon:UsersRound,label:'Навчальні групи',allow:true},{id:'assignments',icon:UsersRound,label:'Викладачі та студенти',allow:role!=='student'},{id:'users',icon:ShieldCheck,label:'Користувачі та ролі',allow:role==='admin'},{id:'profile',icon:UserRound,label:'Мій профіль',allow:true}];
  return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark"><BookOpenText size={22}/></div><div className="brand-name">study<span>flow.</span><small>твій навчальний простір</small></div></div><div className="nav-caption">РОБОЧИЙ ПРОСТІР</div><nav className="nav-list" aria-label="Основне меню StudyFlow">{menu.filter(x=>x.allow).map(item=><button key={item.id} onClick={()=>item.id==='notifications'?openNotifications():setPage(item.id)} className={`nav-item ${page===item.id?'active':''}`}><item.icon size={19}/>{item.label}{item.id==='notifications'&&unread>0&&<b className="nav-count">{unread}</b>}</button>)}</nav><div className="sidebar-filler"/><div className="sidebar-tip"><CalendarDays size={17}/>Усі інструменти навчання в одному просторі.</div><button className="sidebar-user" onClick={()=>setPage('profile')}><AvatarCircle profile={profile}/><div><strong>{profile?.full_name}</strong><small>{ROLE_LABEL[role]}</small></div><ChevronRight size={17}/></button></aside>
  <div className="main-area"><header className="topbar"><div className="crumb">Мій простір <ChevronRight size={14}/> <strong>{menu.find(m=>m.id===page)?.label}</strong></div><div className="topbar-actions"><span className="role-indicator" aria-label="Поточна роль">{ROLE_LABEL[role]}</span><span className="time-zone">● Час за Києвом</span><button title="Перемкнути тему" className="icon-btn" onClick={()=>setDark(d=>!d)}>{dark?<Sun size={18}/>:<Moon size={18}/>}</button><button className="icon-btn notification-bell" title="Сповіщення" onClick={openNotifications}><Bell size={19}/>{unread>0&&<i/>}</button><AvatarCircle profile={profile} size="small"/></div></header><main className="main-content">{inviteToken&&<div className="panel invite-banner"><strong>Запрошення до навчальної групи</strong><p>Прийняти запрошення та приєднатися до групи? Посилання перевіряється під час вступу.</p><button className="btn primary" disabled={inviteBusy} onClick={()=>void acceptInvite()}>{inviteBusy?'Перевірка…':'Приєднатися'}</button><button className="btn light" onClick={()=>{setInviteToken('');window.history.replaceState(null,'',location.pathname);}}>Відхилити</button></div>}{error&&<div className="banner error" role="alert"><CircleAlert size={18}/><span>{error}</span><button onClick={()=>setError('')}><X size={17}/></button></div>}
  {page==='schedule'&&<><section className="hero"><div><div className="eyebrow">НАВЧАЛЬНИЙ РОЗКЛАД</div><h1>{role==='admin'?'Розклад закладу':role==='teacher'?'Мої заняття':'Мій розклад'}<span>.</span></h1><p>{role==='admin'?'Заняття, викладачі та групи в одному календарі.':role==='teacher'?'Ваші заняття й зміни розкладу в одному місці.':'Зручний огляд занять і важливих оновлень.'}</p></div><div className="hero-actions"><button className="btn light" onClick={async()=>{await navigator.clipboard.writeText(location.origin);notify('Посилання скопійовано');}}><Copy size={17}/> Поділитися</button>{canCreate&&<button className="btn primary" onClick={()=>setEdit({lesson:null,date:selectedDate})}><Plus size={17}/> Додати заняття</button>}</div></section>
  <div className="metric-grid metrics-5"><div className="metric"><div className="metric-ico sky"><BookOpenText size={19}/></div><span>Занять у періоді</span><strong>{stats.total}</strong><small>За вибрані дати</small></div><div className="metric"><div className="metric-ico purple"><Clock3 size={19}/></div><span>Години навчання</span><strong>{durationText(stats.minutes)}</strong><small>Без скасованих занять</small></div><div className="metric"><div className="metric-ico mint"><Check size={19}/></div><span>Проведених</span><strong>{stats.completed}</strong><small>У вибраному періоді</small></div><div className="metric"><div className="metric-ico amber"><CalendarRange size={19}/></div><span>Перенесених</span><strong>{stats.rescheduled}</strong><small>У вибраному періоді</small></div><div className="metric"><div className="metric-ico sky"><X size={19}/></div><span>Скасованих</span><strong>{stats.cancelled}</strong><small>У вибраному періоді</small></div></div>
  <section className="calendar-section"><div className="section-top"><div><div className="eyebrow">НАВЧАЛЬНИЙ ПЛАНЕР</div><h2>Календар занять</h2><p>Перемикай тижні або місяці та переглядай конкретні дати.</p></div><div className="period-controls"><button className="icon-btn" title="Попередній період" onClick={()=>movePeriod(-1)}><ChevronLeft size={20}/></button><strong>{view==='week'?`${showDate(rangeStart)} — ${showDate(rangeEnd,{day:'numeric',month:'long',year:'numeric'})}`:showDate(monthStart(selectedDate),{month:'long',year:'numeric'})}</strong><button className="icon-btn" title="Наступний період" onClick={()=>movePeriod(1)}><ChevronRight size={20}/></button><button className="btn light compact" onClick={()=>setSelectedDate(today)}>Сьогодні</button></div></div><div className="filters"><div className="segmented"><button onClick={()=>setView('week')} className={view==='week'?'selected':''}>Тиждень</button><button onClick={()=>setView('month')} className={view==='month'?'selected':''}>Місяць</button></div><label className="search"><Search size={17}/><input aria-label="Пошук занять" placeholder="Пошук заняття чи викладача" value={search} onChange={e=>setSearch(e.target.value)}/></label>{role==='admin'&&<select aria-label="Викладач" value={pickedTeacher} onChange={e=>setPickedTeacher(e.target.value)}><option value="">Усі викладачі</option>{teachers.map(t=><option value={t.id} key={t.id}>{t.full_name}</option>)}</select>}<select aria-label="Статус" value={pickedStatus} onChange={e=>setPickedStatus(e.target.value)}><option value="">Усі статуси</option>{Object.entries(STATUS_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><select aria-label="Фільтр групи" value={pickedGroup} onChange={e=>setPickedGroup(e.target.value)}><option value="">Усі доступні групи</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><input aria-label="Перейти до дати" type="date" className="date-jump" value={selectedDate} onChange={e=>setSelectedDate(e.target.value)}/><button className="icon-btn" title="Оновити" onClick={()=>void reloadLessons()}><RefreshCw size={18}/></button><button className="btn light compact" onClick={exportCsv}><Download size={16}/> Excel (CSV)</button><button className="btn light compact" onClick={()=>window.print()}><Printer size={16}/> PDF / Друк</button></div>
  {view==='week'?<div className="week-board">{days.map((d,i)=><div key={d} className={`day-col ${d===today?'today':''}`}><div className="day-header"><small>{SHORT_DAYS[i]} · {showDate(d)}</small><strong>{DAYS[i]}</strong><span>{visibleLessons.filter(l=>l.lesson_date===d).length} занять</span></div><div className="day-content" onDragOver={e=>{if(canCreate)e.preventDefault();}} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/studyflow-lesson');const match=lessons.find(l=>l.id===id);if(match&&roleCanEdit(role,match,viewer))setDragProposal({lesson:match,date:d,starts:time(match.starts_at),ends:time(match.ends_at)});}}>{loading?<div className="empty-day">Завантаження…</div>:visibleLessons.filter(l=>l.lesson_date===d).length===0&&!reschedules.some(m=>m.old_date===d)?<div className="empty-day"><CalendarDays size={24}/><strong>Поки вільно</strong><small>Час для себе ✨</small></div>:visibleLessons.filter(l=>l.lesson_date===d).map(l=><ScheduleCard key={l.id} lesson={l} teacher={teacherMap[l.teacher_id||'']||''} student={teacherMap[l.student_id||'']||''} group={groupMap[l.group_id||'']||''} canEdit={roleCanEdit(role,l,viewer)} onClick={()=>setEdit({lesson:l,date:d})} onDetails={()=>{setLessonDetails(l);setDetailMoves([]);}}/>)}{reschedules.filter(m=>m.old_date===d&&(!pickedTeacher||m.teacher_id===pickedTeacher)&&(!pickedGroup||m.group_id===pickedGroup)).map(m=><div className="moved-ghost" key={m.id}><span className="status status-rescheduled">Перенесено на іншу дату</span><strong>{m.lesson_title}</strong><small>Було: {time(m.old_starts_at)}–{time(m.old_ends_at)}</small><span>Стало: {m.new_date} · {time(m.new_starts_at)}–{time(m.new_ends_at)}</span><button className="lesson-details-btn" type="button" onClick={()=>{setSelectedDate(m.new_date);setView('week');}}>Перейти до нової дати <ArrowRight size={13}/></button></div>)}{canCreate&&<button className="add-day" onClick={()=>setEdit({lesson:null,date:d})}><Plus size={13}/> Додати</button>}</div></div>)}</div>:<div className="month-board">{SHORT_DAYS.map(d=><strong className="month-weekday" key={d}>{d}</strong>)}{days.map(d=><div key={d} className={`month-day ${d.slice(0,7)!==selectedDate.slice(0,7)?'other-month':''} ${d===today?'today':''}`} onClick={()=>{setSelectedDate(d);setView('week');}}><span>{parseISO(d).getUTCDate()}</span>{visibleLessons.filter(l=>l.lesson_date===d).slice(0,3).map(l=><div className={`month-event ${l.status==='cancelled'?'struck':''}`} key={l.id}>{time(l.starts_at)} {l.title}</div>)}{reschedules.filter(m=>m.old_date===d&&(!pickedTeacher||m.teacher_id===pickedTeacher)&&(!pickedGroup||m.group_id===pickedGroup)).slice(0,2).map(m=><div className="month-event month-moved" key={m.id}>↪ Перенесено: {m.lesson_title} → {m.new_date}</div>)}{visibleLessons.filter(l=>l.lesson_date===d).length>3&&<small>+ ще {visibleLessons.filter(l=>l.lesson_date===d).length-3}</small>}</div>)}</div>}
  <div className="calendar-foot"><span>● {loading?'Завантаження…':'Дані синхронізуються через Supabase'}</span><span>За замовчуванням — час Києва</span></div></section></>}
  {page==='statistics'&&<StatisticsDashboard profiles={profiles} groups={groups} members={members} role={role} viewer={viewer} onOpenUsers={()=>setPage(role==='admin'?'users':'groups')} onOpenLessons={(date,opts)=>{setSelectedDate(date);setView('week');setPickedTeacher(opts?.teacherId||'');setPickedGroup(opts?.groupId||'');setPickedStatus(opts?.status||'');setSearch(opts?.subject||'');setPage('schedule');}}/>}
  {page==='attendance'&&<AttendancePanel key={attendanceLesson?.id||'attendance'} role={role} viewer={viewer} profiles={profiles} groups={groups} members={members} initialLessonId={attendanceLesson?.id} initialDate={attendanceLesson?.lesson_date}/>}
  {page==='requests'&&<ScheduleRequests role={role} viewer={viewer} profiles={profiles} initialLessonId={requestLesson?.id}/>}
  {page==='notifications'&&<section className="panel-page"><div className="page-heading"><button className="btn light notice-back" onClick={()=>setPage(notificationsFrom)}><ArrowLeft size={18}/> Повернутися</button><div className="eyebrow">ВАЖЛИВІ ОНОВЛЕННЯ</div><h1>Сповіщення <span className="bubble">{unread} нових</span></h1><p>Зміни в доступних тобі заняттях та групах.</p></div><div className="panel list-panel notice-list">{notices.length?notices.map(n=><div key={n.id} className={`notification ${n.read_at?'read':''}`}><span className="round-ico"><Bell size={18}/></span><div><strong>{n.message}</strong><small>{localDateTime(n.created_at)}</small></div><div className="notification-actions">{n.lesson_id&&<button className="btn light compact" onClick={()=>void openNoticeLesson(n)}>Деталі</button>}{!n.read_at&&<button className="btn light compact" onClick={()=>void markNotice(n.id)}><Check size={15}/> Прочитано</button>}</div></div>):<div className="blank-state"><Bell size={31}/><h3>Ще немає сповіщень</h3><p>Коли у твоїй групі зміняться заняття, вони з’являться тут.</p></div>}</div></section>}
  {page==='audit'&&role!=='student'&&<section className="panel-page"><div className="page-heading"><div className="eyebrow">ПРОЗОРА ІСТОРІЯ</div><h1>Журнал змін</h1><p>Автоматично створюється в базі даних. {role==='admin'?'Тобі доступні всі події.':'Тобі доступні власні дії.'}</p></div><div className="panel list-panel"><div className="inline-tools"><button className="btn light compact" onClick={()=>void reloadAudit()}><RefreshCw size={16}/> Оновити</button><span>Останні 200 записів</span></div>{history.length?history.map(h=><details className="audit-row" key={h.id}><summary><div className="audit-icon"><FileClock size={19}/></div><div><strong>{h.lesson_title}</strong><small>{h.actor_name} · {h.actor_role} · {localDateTime(h.occurred_at)}</small></div><span className="status">{({created:'Створення',updated:'Редагування',rescheduled:'Перенесення',deleted:'Видалення'} as const)[h.action]}</span><ChevronRight size={16}/></summary><div className="audit-detail"><div><h4>Було</h4><pre>{h.old_data?JSON.stringify(h.old_data,null,2):'—'}</pre></div><div><h4>Стало</h4><pre>{h.new_data?JSON.stringify(h.new_data,null,2):'—'}</pre></div></div></details>):<div className="blank-state"><FileClock size={30}/><h3>Подій поки немає</h3><p>Перше редагування створить новий запис.</p></div>}</div></section>}
  {page==='groups'&&<GroupManager groups={groups} members={members} profiles={profiles} users={users} role={role} onRefresh={async()=>{await reloadDirectory();if(role==='admin')await reloadUsers();}} onNotice={notify} onError={onError}/>}
  {page==='assignments'&&role!=='student'&&<section className="panel-page"><div className="page-heading"><div className="eyebrow">ПЕРСОНАЛЬНЕ НАВЧАННЯ</div><h1>Викладачі та студенти</h1><p>Один студент може навчатися в кількох викладачів. Для індивідуального заняття вибери студента у формі уроку.</p></div><div className="panel list-panel">{assignments.map(a=><div className="user-row" key={a.id}><div className="avatar">{(teacherMap[a.teacher_id]||'В')[0]}</div><div><strong>{teacherMap[a.teacher_id]||'Викладач'} → {teacherMap[a.student_id]||'Студент'}</strong><small>{a.subject}</small></div>{role==='admin'&&<button type="button" className="btn danger compact" onClick={()=>void deleteAssignment(a.id)}><Trash2 size={15}/> Видалити</button>}</div>)}{!assignments.length&&<div className="blank-state">Призначень поки немає</div>}</div>{role==='admin'&&<form className="panel stack-form" onSubmit={addAssignment}><h2>Закріпити студента</h2><label>Викладач<select required value={assignmentTeacher} onChange={e=>setAssignmentTeacher(e.target.value)}><option value="">Обери викладача</option>{teachers.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>Студент<select required value={assignmentStudent} onChange={e=>setAssignmentStudent(e.target.value)}><option value="">Обери студента</option>{students.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>Предмет<input required maxLength={120} value={assignmentSubject} onChange={e=>setAssignmentSubject(e.target.value)} placeholder="Англійська мова"/></label><button type="submit" className="btn primary"><Plus size={16}/> Закріпити</button></form>}</section>}
  {page==='users'&&role==='admin'&&<section className="panel-page"><div className="page-heading"><div className="eyebrow">КЕРУВАННЯ ДОСТУПОМ</div><h1>Користувачі та ролі</h1><p>Тільки адміністратор може змінювати роль. Нові акаунти отримують роль студента.</p></div><div className="panel list-panel">{users.map(u=><div className="user-row" key={u.id}><div className="avatar">{u.full_name[0]||'К'}</div><div><strong>{u.full_name}</strong><small>{u.email}</small></div><select aria-label={`Роль ${u.full_name}`} value={u.role} onChange={e=>void changeRole(u.id,e.target.value as Role)}>{Object.entries(ROLE_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div>)}{users.length===0&&<div className="blank-state">Користувачів ще немає</div>}</div></section>}
  {page==='profile'&&<section className="panel-page"><div className="page-heading"><div className="eyebrow">ПЕРСОНАЛЬНО</div><h1>Мій профіль</h1><p>Дані прив’язані до твого облікового запису.</p></div><div className="panel profile-pane"><div className="profile-main"><AvatarCircle profile={profile} size="huge"/><h2>{profile?.full_name}</h2><span className="role-tag">{ROLE_LABEL[role]}</span><p>{session.user.email}</p><div className="personal-stats"><span><strong>{visibleLessons.filter(l=>l.created_by===viewer).length}</strong> створено мною за період</span><span><strong>{notices.length}</strong> сповіщень</span></div><button className="btn light" onClick={async()=>{await supabase?.auth.signOut();setPage('schedule');}}><LogOut size={16}/> Вийти з акаунта</button></div><form onSubmit={updateProfile} className="stack-form profile-form"><h3>Редагувати профіль</h3><label>Ім'я та прізвище<input required maxLength={100} value={profileName} onChange={e=>setProfileName(e.target.value)}/></label><label>Аватар (URL зображення)<input type="url" maxLength={500} value={profileAvatar} onChange={e=>setProfileAvatar(e.target.value)} placeholder="https://..."/></label><label>Курс (за наявності)<select value={profileCourse} onChange={e=>setProfileCourse(e.target.value)}><option value="">Не вказано</option>{Array.from({length:8},(_,i)=><option key={i+1} value={i+1}>{i+1} курс</option>)}</select></label><label>Спеціальність (за наявності)<input maxLength={120} value={profileSpecialty} onChange={e=>setProfileSpecialty(e.target.value)} placeholder="Не вказано"/></label><label>Факультет<input maxLength={120} value={profileFaculty} onChange={e=>setProfileFaculty(e.target.value)} placeholder="За наявності"/></label><label>Спеціалізація / предмети<input maxLength={120} value={profileSpecialization} onChange={e=>setProfileSpecialization(e.target.value)} placeholder="За наявності"/></label><label>Про себе<textarea rows={3} maxLength={1000} value={profileBio} onChange={e=>setProfileBio(e.target.value)} placeholder="Додаткова інформація"/></label><label>Роль<input value={ROLE_LABEL[role]} disabled readOnly/></label><button className="btn primary" disabled={busy} type="submit"><Save size={16}/> Зберегти зміни</button></form></div></section>}
  <footer>study<span className="blue">flow.</span> © {new Date().getFullYear()} <span>Навчальний простір з турботою 💙</span></footer></main></div>
  {lessonDetails&&<LessonDetails lesson={lessonDetails} teacher={teacherMap[lessonDetails.teacher_id||'']||''} group={groupMap[lessonDetails.group_id||'']||''} students={lessonDetails.student_id?[teacherMap[lessonDetails.student_id]||'Студент']:members.filter(m=>m.group_id===lessonDetails.group_id&&m.member_role==='student').map(m=>teacherMap[m.user_id]||'Студент')} history={detailMoves} canEdit={roleCanEdit(role,lessonDetails,viewer)} onEdit={()=>{setEdit({lesson:lessonDetails,date:lessonDetails.lesson_date});setLessonDetails(null);}} onAttendance={()=>{setAttendanceLesson(lessonDetails);setPage('attendance');setLessonDetails(null);}} onRequest={()=>{setRequestLesson(lessonDetails);setPage('requests');setLessonDetails(null);}} originalTeacher={teacherMap[lessonDetails.original_teacher_id||'']||''} onClose={()=>setLessonDetails(null)}/>}{edit&&<LessonEditor key={`${edit.lesson?.id||'new'}-${edit.date}`} lesson={edit.lesson} initialDay={edit.date} role={role} viewer={viewer} groups={groups.filter(g=>role==='admin'||members.some(m=>m.group_id===g.id&&m.user_id===viewer&&m.member_role==='teacher'))} teachers={teachers} students={students} assignments={assignments} selectedGroup={pickedGroup} busy={busy} onSave={saveLesson} onRepeat={createSeries} onSeriesEdit={editSeries} onRemove={deleteLesson} onClose={()=>setEdit(null)}/>}{dragProposal&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setDragProposal(null);}}><div className="dialog" role="dialog" aria-modal="true" aria-labelledby="drag-title"><div className="dialog-head"><h2 id="drag-title">Перенести заняття</h2><button className="icon-btn" onClick={()=>setDragProposal(null)} disabled={busy}><X size={18}/></button></div><div className="learning-transfer"><strong>{dragProposal.lesson.title}</strong><p>Було: {dragProposal.lesson.lesson_date} · {time(dragProposal.lesson.starts_at)}–{time(dragProposal.lesson.ends_at)}</p><label>Нова дата<input type="date" value={dragProposal.date} onChange={e=>setDragProposal(old=>old?{...old,date:e.target.value}:null)}/></label><label>Початок<input type="time" value={dragProposal.starts} onChange={e=>setDragProposal(old=>old?{...old,starts:e.target.value}:null)}/></label><label>Завершення<input type="time" value={dragProposal.ends} onChange={e=>setDragProposal(old=>old?{...old,ends:e.target.value}:null)}/></label><p>База перевірить зайнятість викладача й студентів. За конфлікту зміни не збережуться.</p><div className="dialog-actions"><button className="btn light" onClick={()=>setDragProposal(null)}>Скасувати</button><button className="btn primary" disabled={busy||dragProposal.starts>=dragProposal.ends} onClick={()=>void confirmDrag()}>Підтвердити перенесення</button></div></div></div></div>}{toast&&<div className="toast"><Check size={18}/>{toast}<button onClick={()=>setToast('')} aria-label="Закрити"><X size={15}/></button></div>}</div>;
}
